PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Safe_Haven_(film) dbr:Nomad:_In_the_Footsteps_of_Bruce_Chatwin }

  { ?film dbo:director ?director } UNION { ?film dbp:director ?director }

  OPTIONAL {
    { ?director dbo:birthDate ?birthDate } UNION { ?director dbp:birthDate ?birthDate }
  }
}
LIMIT 100

